// ── SCI fundraising: settings for this workflow ─────────────────────────────
// Non-secret settings only. Keys, tokens and passwords live in n8n
// credentials (see automations/README.md), never here.
// Fill in the Microsoft IDs once; the README says where each one comes from.
return [{ json: {
  siteUrl: 'https://sanctuarymetrics.vercel.app',           // the dashboard; /api/fundraising-state lives here
  githubRepo: 'Brian2169fdsa/sanctuarymetrics',             // owner/name
  githubBranch: 'main',                                      // the branch Vercel deploys
  tz: 'America/Phoenix',
  donorboxApi: 'https://donorbox.org/api/v1',
  majorGiftUsd: 250,
  // Microsoft 365 (SCI's own tenant)
  sharepointSiteId: '',         // Graph site id of SCI's SharePoint site
  donorListId: '',              // the private "SCI Donors" list (the only place donor details land)
  teamId: '',                   // Teams team for the fundraising channel
  channelId: '',                // the fundraising channel
  plannerPlanId: '',            // Planner plan for follow-up tasks
  plannerBucketId: '',          // bucket in that plan
  joeyUserId: '',               // Joey's Entra user id (major-gift call tasks)
  senderMailbox: '',            // the monitored SCI address that sends donor email
  digestRecipients: [],         // weekly digest email addresses
  orgName: 'Sanctuary Community Initiative',
  orgAddress: '11645 N Cave Creek Rd, Phoenix, AZ 85020',
  donorPortalUrl: 'https://donorbox.org/user/sign_in',      // VERIFY: Donorbox donor login page
  wallOfSupportUrl: 'https://www.sanctuaryci.org/The-Sanctuary.html',
  // Safety switch: until the email templates are reviewed and approved, every
  // donor email goes to senderMailbox instead of the donor, marked [REVIEW].
  emailsApproved: false,
  // Social queue (f9): a scheduling tool, if one is connected. Leave false to
  // get Teams reminders only. Auto-posting also needs the switch on the page.
  schedulerConnected: false
} }];

// f7 Donor journey and f8 Lapsed donors, once a day over the private donor list.
// Unsubscribe replies in the sending mailbox are applied first, so they are
// honored in this run and in every other sequence (f4-f6 read the same column).
// shared helpers, pasted at the top of Code nodes that need them
const CFG = $('Config').first().json;
function phxDate(d) {
  return DateTime.fromJSDate(d instanceof Date ? d : new Date(d)).setZone(CFG.tz).toISODate();
}
function phxNow() { return DateTime.now().setZone(CFG.tz); }
function money(n) { return '$' + Math.round(Number(n) || 0).toLocaleString('en-US'); }
function initial(s) { s = String(s || '').trim(); return s ? s[0].toUpperCase() + '.' : ''; }
function shortName(first, last) { return (String(first || '').trim() || 'A donor') + (last ? ' ' + initial(last) : ''); }
function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
function rows(nodeName) {
  // items from an HTTP node; tolerates the empty {} that alwaysOutputData adds
  return $(nodeName).all().map(function (i) { return i.json; }).filter(function (x) { return x && x.id !== undefined; });
}
function graphRows(nodeName) {
  // SharePoint list items across pages (each page is one item with .value)
  const out = [];
  $(nodeName).all().forEach(function (i) { (i.json.value || []).forEach(function (r) { out.push(r); }); });
  return out;
}
function emailHtml(bodyHtml) {
  // every donor email: the body, a way to unsubscribe, and SCI's street address
  const unsub = 'mailto:' + CFG.senderMailbox + '?subject=Unsubscribe';
  return '<div style="font-family:Arial,sans-serif;font-size:15px;line-height:1.55;color:#22323B">' + bodyHtml +
    '<hr style="border:0;border-top:1px solid #ddd;margin:24px 0 12px">' +
    '<p style="font-size:12px;color:#6C7C86">' + esc(CFG.orgName) + ' · ' + esc(CFG.orgAddress) + ' · EIN 39-2503445<br>' +
    'You are receiving this because you gave to ' + esc(CFG.orgName) + '. ' +
    '<a href="' + unsub + '">Unsubscribe</a> (or reply with the word unsubscribe) and we will stop all fundraising email to you.</p></div>';
}
function mail(to, subject, bodyHtml) {
  // a Graph sendMail request; while emailsApproved is false it goes to the review mailbox
  const review = !CFG.emailsApproved;
  return {
    url: 'https://graph.microsoft.com/v1.0/users/' + encodeURIComponent(CFG.senderMailbox) + '/sendMail',
    body: { message: {
      subject: (review ? '[REVIEW, would go to a donor] ' : '') + subject,
      body: { contentType: 'HTML', content: emailHtml(bodyHtml) },
      toRecipients: [{ emailAddress: { address: review ? CFG.senderMailbox : to } }]
    }, saveToSentItems: true }
  };
}
function teams(html) {
  return { url: 'https://graph.microsoft.com/v1.0/teams/' + CFG.teamId + '/channels/' + CFG.channelId + '/messages',
           body: { body: { contentType: 'html', content: html } } };
}

const today = phxNow();
const donors = graphRows('GET donor list');
const listBase = 'https://graph.microsoft.com/v1.0/sites/' + CFG.sharepointSiteId + '/lists/' + CFG.donorListId + '/items';
const out = [], count = { f7: 0, f8: 0, unsub: 0 };
function graph(method, url, body, flow) { out.push({ json: { method: method, url: url, body: body, flow: flow } }); }

/* unsubscribe replies */
const asked = {};
$('GET unsubscribe replies').all().forEach(function (i) {
  (i.json.value || []).forEach(function (m) {
    const from = (((m.from || {}).emailAddress || {}).address || '').toLowerCase();
    if (from && /unsubscribe/i.test((m.subject || '') + ' ' + (m.bodyPreview || ''))) { asked[from] = true; }
  });
});

/* TEMPLATES: review the wording, then set emailsApproved in Config. */
const T = {
  day1: ['Thank you from Joey', function (f) { return '<p>Dear ' + esc(f || 'friend') + ',</p><p>Thank you for your gift to Sanctuary Community Initiative. ' +
    'When treatment ends, the need for a safe bed, a ride to work and a valid ID does not. Your gift helps fund exactly that.</p><p>[REVIEW: Joey\'s own words]</p><p>Joey<br>[Title]</p>'; }],
  day14: ['What your gift makes possible', function (f) { return '<p>Dear ' + esc(f || 'friend') + ',</p><p>Two weeks ago you gave to the safety net. ' +
    'Among Sanctuary participants since July 2025, 94% had no new arrests across all check-ins. Stable housing and practical support are what that number is made of.</p>' +
    '<p>[REVIEW: one released story or a housing staff note, if available]</p><p>[Signature]</p>'; }],
  day60: ['Be the steady support', function (f) { return '<p>Dear ' + esc(f || 'friend') + ',</p><p>A one-time gift covers a ride. A monthly gift keeps a bed open. ' +
    'Would you join The Sanctuary, our monthly givers, from $10 a month? <a href="' + esc(CFG.wallOfSupportUrl) + '">Join The Sanctuary</a>.</p><p>[Signature]</p>'; }],
  month11: ['A year of support', function (f) { return '<p>Dear ' + esc(f || 'friend') + ',</p><p>Almost a year ago you gave to Sanctuary Community Initiative. ' +
    'Would you renew your support this year? [REVIEW: link to the current campaign]</p><p>[Signature]</p>'; }]
};

donors.forEach(function (r) {
  const f = r.fields || {}, email = String(f.Email || '').toLowerCase();
  if (email && asked[email] && !f.Unsubscribed) { graph('PATCH', listBase + '/' + r.id + '/fields', { Unsubscribed: true }, 'unsub'); count.unsub++; f.Unsubscribed = true; }
  const patch = {};
  /* f8: lapsed — no gift in 12 months */
  if (f.LastGiftDate && DateTime.fromISO(String(f.LastGiftDate).slice(0, 10)) <= today.minus({ months: 12 }) && f.Segment !== 'october-reactivation') {
    patch.Segment = 'october-reactivation'; count.f8++;
  }
  /* f7: one journey step per donor per day, in order */
  if (!f.Unsubscribed && email && f.FirstGiftDate) {
    const days = Math.floor(today.diff(DateTime.fromISO(String(f.FirstGiftDate).slice(0, 10)), 'days').days);
    const sinceLast = f.LastGiftDate ? today.diff(DateTime.fromISO(String(f.LastGiftDate).slice(0, 10)), 'months').months : 0;
    const step = f.JourneyStep || 'new';
    let send = null, next = null;
    if (step === 'new' && days >= 1) { send = 'day1'; next = 'thanked'; }
    else if (step === 'thanked' && days >= 14) { send = 'day14'; next = 'impact'; }
    else if (step === 'impact' && days >= 60) { if (!f.Recurring) { send = 'day60'; } next = 'upgrade-asked'; }
    else if ((step === 'upgrade-asked' || step === 'renewed') && sinceLast >= 11 && f.JourneyRenewalFor !== String(f.LastGiftDate)) {
      send = 'month11'; next = 'renewed'; patch.JourneyRenewalFor = String(f.LastGiftDate);
    }
    if (next) { patch.JourneyStep = next; patch.JourneyAt = today.toISODate(); }
    if (send) {
      const m = mail(email, T[send][0], T[send][1](f.FirstName));
      graph('POST', m.url, m.body, 'f7'); count.f7++;
    }
  }
  if (Object.keys(patch).length) { graph('PATCH', listBase + '/' + r.id + '/fields', patch, 'f7'); }
});
$getWorkflowStaticData('global').counts = count;
return out;

// one run report per automation in this workflow
const c = $getWorkflowStaticData('global').counts || {};
const s = $getWorkflowStaticData('global').summary;
return ["f7","f8"].map(function (id) { return { json: { runId: id, runMessage: s || (c[id] !== undefined ? c[id] + ' sent' : '') } }; });
